function esc15(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function cap15(s){s=String(s||'');return s.charAt(0).toUpperCase()+s.slice(1);}
var B="https://image.qwenlm.ai/public_source/cf785bab-295b-41b7-b135-c32bc2c7d2ed/";
function P(a,b){return B+a+"-1d0c-4729-8d1b-f4c229283bb0"+b+".png";}
function phFallback(k){var p=PHOTOS[k];var t=((p&&p.caption)||k).replace(/["<>]/g,'');var svg='<svg xmlns="http://www.w3.org/2000/svg" width="240" height="150"><rect width="240" height="150" fill="#2a0a0e"/><rect x="0" y="0" width="240" height="150" fill="none" stroke="#8f1d2c" stroke-width="3"/><text x="120" y="68" font-family="Arial" font-size="13" fill="#ff8a80" text-anchor="middle">'+t.slice(0,26)+'</text><text x="120" y="92" font-family="Arial" font-size="11" fill="#ffd9d0" text-anchor="middle">photo hors-ligne</text></svg>';return 'data:image/svg+xml;utf8,'+encodeURIComponent(svg);}
function vePhoto(k){var p=PHOTOS[k];var cap=p?p.caption:k;var url=p?p.url:'';return '<img src="'+url+'" alt="'+esc15(cap)+'" loading="lazy" class="photo-thumb" onclick="openLightbox(\''+k+'\')" onerror="this.onerror=null;this.src=phFallback(\''+k+'\')">';}
function veRow(ks){return '<div class="photo-row">'+(ks||[]).map(vePhoto).join('')+'</div>';}
